function ticketsDeflected(teams, avgTicketsIfManual) {
  const onPath = teams.filter((t) => t.onGoldenPath);
  return onPath.reduce(
    (sum, t) => sum + Math.max(0, avgTicketsIfManual - t.manualTicketsThisMonth),
    0,
  );
}

